descriptor.templateCss:
.dg-sync-card {
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  background: linear-gradient(160deg, rgba(14, 25, 16, 0.95) 0%, rgba(8, 15, 9, 0.98) 100%);
  border-radius: 14px;
  border: 1px solid rgba(100, 184, 86, 0.22);
  border-top: 3.5px solid #06b6d4;
  padding: 16px 20px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.45);
}
.card-header-sync {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.title-sync {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.6px;
  color: #94a3b8;
}
.icon-sync { font-size: 16px; }
.badge-sync {
  font-size: 11px;
  font-weight: 700;
  padding: 2px 10px;
  border-radius: 20px;
}
.badge-sync.in-sync {
  color: #64B856;
  border: 1.5px solid #64B856;
  background: rgba(100, 184, 86, 0.1);
}
.badge-sync.out-sync {
  color: #ef4444;
  border: 1.5px solid #ef4444;
  background: rgba(239, 68, 68, 0.15);
}
.sync-body-grid {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin: 6px 0;
}
.freq-col {
  display: flex;
  flex-direction: column;
  align-items: center;
  flex: 1;
}
.sync-sub { font-size: 10px; font-weight: 700; color: #94a3b8; letter-spacing: 0.5px; }
.freq-num-group { display: flex; align-items: baseline; gap: 4px; margin: 2px 0; }
.freq-num { font-size: 32px; font-weight: 800; color: #06b6d4; line-height: 1; }
.freq-unit { font-size: 16px; font-weight: 600; color: #94a3b8; }
.freq-gauge-bar {
  width: 140px;
  height: 6px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 3px;
  position: relative;
  margin-top: 4px;
}
.gauge-zone.safe {
  position: absolute;
  left: 37.5%;
  width: 25%;
  height: 100%;
  background: #64B856;
  border-radius: 2px;
}
.gauge-pointer {
  position: absolute;
  top: -4px;
  width: 4px;
  height: 14px;
  background: #f1f5f9;
  border-radius: 2px;
  box-shadow: 0 0 6px #06b6d4;
  transition: left 0.3s ease;
}
.gauge-labels {
  width: 140px;
  display: flex;
  justify-content: space-between;
  font-size: 9px;
  color: #64748b;
  margin-top: 3px;
}
.sync-sep { width: 1px; height: 55px; background: rgba(148, 163, 184, 0.15); }
.volt-col {
  display: flex;
  flex-direction: column;
  align-items: center;
  flex: 1;
}
.volt-table {
  display: flex;
  flex-direction: column;
  gap: 3px;
  width: 130px;
  margin-top: 4px;
}
.v-row { display: flex; justify-content: space-between; font-size: 12px; }
.v-tag { color: #94a3b8; font-weight: 600; }
.v-num { color: #f1f5f9; font-weight: 700; }
.card-footer-sync {
  display: flex;
  justify-content: space-between;
  font-size: 11px;
  color: #64748b;
  border-top: 1px solid rgba(148, 163, 184, 0.12);
  padding-top: 6px;
  margin-top: 4px;
}

descriptor.controllerScript:
self.onInit = function() { self.onDataUpdated(); };
self.onDataUpdated = function() {
  var data = self.ctx.data;
  var hz = 60.02, vu = 220.4, vv = 219.8, vw = 220.1;

  if (data && data.length > 0) {
    for (var i = 0; i < data.length; i++) {
      var item = data[i];
      if (item.data && item.data.length > 0) {
        var v = parseFloat(item.data[item.data.length - 1][1]);
        var k = (item.dataKey.label || item.dataKey.name || "").toLowerCase();
        if (!isNaN(v)) {
          if (k.indexOf('frecuencia') !== -1 || k.indexOf('hz') !== -1 || i === 0) hz = v;
          else if (k.indexOf('tension_fase_u') !== -1 || i === 1) vu = v;
          else if (k.indexOf('tension_fase_v') !== -1 || i === 2) vv = v;
          else if (k.indexOf('tension_fase_w') !== -1 || i === 3) vw = v;
        }
      }
    }
  }

  // Rango tacómetro 58 a 62 Hz
  var minG = 58.0, maxG = 62.0;
  var pointerPct = ((hz - minG) / (maxG - minG)) * 100;
  pointerPct = Math.max(0, Math.min(100, pointerPct));

  var inSync = hz >= 59.5 && hz <= 60.5;
  var container = self.ctx.$container ? self.ctx.$container[0] : null;

  if (container) {
    var elHz = container.querySelector('#hz-val');
    if (elHz) elHz.textContent = hz.toFixed(2);

    var elPtr = container.querySelector('#freq-pointer');
    if (elPtr) elPtr.style.left = pointerPct + '%';

    var elBadge = container.querySelector('#sync-badge');
    if (elBadge) {
      elBadge.textContent = inSync ? 'SINCRONIZADO (' + hz.toFixed(1) + ' Hz)' : 'FUERA TOLERANCIA (' + hz.toFixed(1) + ' Hz)';
      elBadge.className = 'badge-sync ' + (inSync ? 'in-sync' : 'out-sync');
    }

    var elVu = container.querySelector('#vu-val');
    var elVv = container.querySelector('#vv-val');
    var elVw = container.querySelector('#vw-val');
    if (elVu) elVu.textContent = vu.toFixed(1) + ' V';
    if (elVv) elVv.textContent = vv.toFixed(1) + ' V';
    if (elVw) elVw.textContent = vw.toFixed(1) + ' V';
  }
};
self.onDestroy = function() {};
